  str_world_boss_leveldesc_hard_7101001 = [[
- Os aurorianos ganham 1 ladrilho aprimorado para cada 3 ladrilhos que movem.
- Aumenta <color=#cc0e0e>Dano do Combo em Cadeia</color> tomado por monstros em 10% por rodada, e reduz <color=#cc0e0e>ataque normal</color> dano recebido por rodada em 10%.]],
  str_world_boss_bossdesc_7101007 = "Contra-dano do elemento auroriano +100%.\nLadrilhos nos quais os aurorianos geram objetos convocáveis são convertidos em ladrilhos cromáticos.",
  str_world_boss_leveldesc_normal_7101007 = "- Quando uma nova convocação auroriana aparece no campo, o ladrilho abaixo dele é convertido em um ladrilho cromático.",
  str_world_boss_leveldesc_hard_7101007 = "- Quando uma nova convocação auroriana aparece no campo, o ladrilho abaixo dele é convertido em um ladrilho cromático.\n- Auroriano <color=#cc0e0e>Dano de Habilidade Ativa</color> aumenta em 100%.\n- Quando o <color=#cc0e0e>HP atual</color> do clone de Augean for superior a 90%, ele se beneficia de 100% de DEF aumentada.",
  str_world_boss_bossdesc_7101003 = "Contra-dano do elemento auroriano +100%.\nQuando há unidades convocadas por aurorianos no campo de batalha, o ATK aumenta em 10%.",
  str_world_boss_leveldesc_normal_7101003 = "- Quando há unidades convocadas por aurorianos no campo de batalha, o ATK do invocador aumenta em 10%.",
  str_world_boss_leveldesc_hard_7101003 = "- Quando há unidades convocadas por aurorianos no campo de batalha, o ATK do invocador aumenta em 10%.\n- Monstros são <color=#cc0e0e>imunes a dano de Habilidade Ativa</color>. O <color=#cc0e0e>dano do Combo em Cadeia</color> recebido aumenta em 30% e o <color=#cc0e0e>dano de ataque normal</color> recebido diminui em 30%.",
  str_world_boss_leveldesc_normal_7101009 = "- Quando um Aurorian Atirador usa um Combo, ele o usará 1 vez extra no ponto de partida.",
  str_world_boss_leveldesc_hard_7101010 = "- Quando um Aurorian Atirador usa um Combo em Cadeia, ele o usará 1 vez extra no ponto de partida.\n- Aurorians causam 50% de dano adicional a <color=#cc0e0e>inimigos que marcaram</color>.\n- Minos' <color=#cc0e0e>DEF aumenta</color> 10%.",
  str_world_boss_bossdesc_7101009 = "Contra-dano do elemento auroriano +100%\nQuando um Sniper Aurorian usa um Chain Combo, ele o usará 1 vez a mais no ponto inicial.",
  str_world_boss_leveldesc_normal_7101112 = "- Se a Habilidade Ativa estiver pronta, o ATQ dos Aurorianos aumenta em 15% nesta rodada.",
  str_world_boss_leveldesc_hard_7101112 = "- Se a Habilidade Ativa estiver pronta, o ATQ dos Aurorianos aumenta em 15% nesta rodada.\n- Aumenta o <color=#cc0e0e>número de Carniceiros convocados para</color> 6.\n- Aumenta o <color=#cc0e0e>dano da Habilidade Ativa</color> dos Aurorianos em 30% e restaura o HP deles em 10% do dano da Habilidade Ativa.",
  str_world_boss_bossdesc_7101112 = "Dano do Contra-Elemento de Aurorians +100%.\nNozard é imune a dano de Ataque Normal e Gloom Ghouls são imunes a dano de habilidade.\nAumenta o ATK dos aurorianos nesta rodada se sua habilidade ativa estiver pronta.",
  str_world_boss_leveldesc_normal_7101013 = "- Quando a habilidade ativa está convertendo as cores dos blocos, causa dano aos inimigos com base no número de blocos vermelhos gerados.",
  str_world_boss_leveldesc_hard_7101013 = "- Quando a habilidade ativa está convertendo cores de casas, causa dano aos inimigos com base no número de casas vermelhas geradas.\n- A <color=#cc0e0e>DEF de Casta aumenta</color> em 20%\n- Quando Casta está <color=#cc0e0e>em uma casa danificada</color>, sua <color=#cc0e0e>DEF é reduzida</color> em 75%",
  str_world_boss_leveldesc_normal_7101011 = "- A cada 3 rodadas, redefine os ladrilhos dentro de 1 aglomerado circundante, gera alguns ladrilhos azuis na borda do mapa.",
  str_world_boss_leveldesc_hard_7101011 = "- <color=#cc0e0e>A cada 2 rodadas</color>, reinicia as casas dentro de 1 círculo ao redor, gera algumas casas azuis na borda do mapa.\n- <color=#cc0e0e>Aumenta o dano do inimigo</color>, enquanto o <color=#cc0e0e>efeito de cura dos Aurorianos</color> aumenta em 80%\n. Quando os Aurorianos <color=#cc0e0e> se curam</color>, isso <color=#cc0e0e>inflige dano verdadeiro nos inimigos</color> de acordo com a quantidade de cura.",
  str_world_boss_bossdesc_7101013 = [[
Dano de Elemento Eficaz dos Aurorians +100%.
Quando a habilidade ativa de um Aurorian gera ladrilhos vermelhos, causa dano aos inimigos.]],
  str_world_boss_bossdesc_7101011 = "Dano de Elemento Eficaz dos Aurorianos +100%.\nSolmorph reinicia as peças ao redor e gera algumas peças azuis.",
  str_world_boss_bossdesc_7001098 = "Dano de Elemento Eficaz Aurorian +100%\nGera uma Runa de Relâmpago a cada rodada e invoca raios em seguida\nGera Ladrilhos de Prisma Amarelo em um padrão em forma de cruz após o desaparecimento da runa",
  str_world_boss_leveldesc_normal_70010981 = "- Gera uma Runa de Relâmpago sob os Aurorianos a cada rodada e convoca raios <color=#cc0e0e>após o término da conexão das peças</color>\n- <color=#cc0e0e>Gera Peças de Prisma Amarelo em um padrão em forma de cruz</color> após o desaparecimento da runa",
  str_world_boss_leveldesc_hard_70010982 = "- Gera uma Runa de Relâmpago sob os Aurorianos a cada rodada e convoca raios <color=#cc0e0e>após o fim da conexão dos ladrilhos</color>\n- <color=#cc0e0e>Gera Ladrilhos de Prisma Amarelo em um padrão em forma de cruz</color> após o desaparecimento da runa\n- O Chefe sofre <color=#cc0e0e>-50% de DMG de Habilidades Ativas</color>\n- Cada <color=#cc0e0e>Acerto de Ataque Normal</color> aumentará o <color=#cc0e0e>Dano do Combo em Cadeia</color> do Auroriano em 2% nesta rodada",
  str_world_boss_leveldesc_normal_7001102 = "- Sempre que lançar uma <color=#cc0e0e>Habilidade Ativa de conversão de casas</color>, também converterá uma casa ao redor do Chefe para o elemento do capitão.",
  str_world_boss_leveldesc_hard_7001102 = "- Sempre que lançar uma <color=#cc0e0e>Habilidade Ativa de conversão de ladrilhos</color>, também converterá um ladrilho ao redor do Chefe para o elemento do capitão.\n- <color=#cc0e0e>Sempre que usar</color> uma Habilidade Ativa a cada rodada, o Chefe recebe 20% <color=#cc0e0e>menos dano de Habilidades Ativas</color>, até 5 pilhas.\n- Cada acerto de <color=#cc0e0e>Ataque Normal</color> aumentará o <color=#cc0e0e>dano do Combo em Cadeia do Auroriano</color> em 4% nesta rodada.",
  str_world_boss_bossdesc_7001102 = "Aumenta o Dano do Contra-Elemento Auroriano em 100%.\nSempre que usar uma Habilidade Ativa de conversão de ladrilhos, também converte ladrilhos ao redor do chefe.",
  str_world_boss_leveldesc_normal_7001104 = "- Quando o <color=#cc0e0e>HP da equipe é maior que 60%</color>, aumenta o ATK de todos os Aurorianos aliados em 15%.\n- Ao entrar no campo de batalha, os Arorianos receberão dano igual a 50% do seu HP máximo.",
  str_world_boss_leveldesc_hard_7001104 = "- Quando o <color=#cc0e0e>HP da equipe é maior que 75%</color>, <color=#cc0e0e>aumenta o ATK de todos os Aurorianos aliados em 25%</color>.\n- Quando o <color=#cc0e0e>HP da equipe cai abaixo de 40%</color>, <color=#cc0e0e>o ATK de todos os Aurorianos aliados diminui em 25%</color>.\n- Ao entrar no campo de batalha, nossos aliados receberão dano igual a 50% de seu HP máximo.\n- <color=#cc0e0e>Cada cura</color> na rodada atual ganha um aumento de 10%, até 20 pilhas.",
  str_world_boss_bossdesc_7001104 = "Aumenta o contra-dano do elemento Auroriano em 100%. O HP Auroriano influencia o dano causado. Ao entrar no campo de batalha, os Aurorianos sofrerão dano igual a 50% de seu HP máximo.",
  str_world_boss_leveldesc_normal_7001105 = [[
- Kanna aparece no campo de batalha para encorajar seus amigos, enquanto converte os 4 ladrilhos ao seu redor em <color=#cc0e0e>ladrilhos vermelhos danificados</color>.
- Quando os Aurorianos passam pelos 4 ladrilhos ao redor de Kanna, <color=#cc0e0e>o contador de combo aumenta em 10</color> para cada ladrilho atravessado.]],
  str_world_boss_leveldesc_hard_7001105 = "- Kanna aparece no campo de batalha para encorajar seus amigos, enquanto converte os 4 ladrilhos ao seu redor em <color=#cc0e0e>ladrilhos vermelhos danificados</color>.\n- Quando os Aurorianos passam pelos 4 ladrilhos ao redor de Kanna, o <color=#cc0e0e>contador de combo aumenta em 10</color> para cada ladrilho atravessado.\n- Na quarta rodada, os tempos de recarga de todas as habilidades Aurorianas são reduzidos em 1.\n- O Imperador do Fim possui a habilidade extremamente ameaçadora <color=#cc0e0e>Fim do Destino</color>.",
  str_world_boss_bossdesc_7001105 = [[
Dano de Elemento Eficaz Aurorian +100%
Kanna aparece no campo de batalha para animar seus amigos com incentivo.]],
  str_world_boss_leveldesc_normal_7001106 = "- Tohru aparece no campo de batalha para encorajar seus amigos, lançando habilidades a cada rodada e causando dano 5 vezes. Esta habilidade também irá resetar os ladrilhos não-amarelos dentro de 1 aglomerado circundante.",
  str_world_boss_leveldesc_hard_7001106 = "- Tohru aparece no campo de batalha para encorajar seus amigos, lançando habilidades a cada rodada para causar dano 5 vezes no total, e redefinindo ladrilhos não-amarelos dentro de 1 cluster circundante.\n- Na quarta rodada, os tempos de recarga de todas as habilidades Aurorian são reduzidos em 1.\n- Schummer possui a habilidade de <color=#cc0e0e>melhorar significativamente seus atributos</color>.",
  str_world_boss_bossdesc_7001106 = [[
Dano de Elemento Eficaz Aurorian +100%
Tohru aparece no campo de batalha para animar seus amigos com incentivo.]],
  str_world_boss_bossdesc_7001110 = [[
Dano do Contra-Elemento Auroriano +100%.
Ataques normais dos aurorianos reduzem pilhas de veneno em si mesmos.]],
  str_world_boss_leveldesc_normal_7001110 = [[
- <color=#cc0e0e>Usar Habilidades Ativas</color> <color=#cc0e0e>gera 2 Ladrilhos Escuros</color> dentro de 1 aglomerado ao redor do chefe.
- Ataques normais dos Aurorianos reduzem as pilhas de veneno em si mesmos.]],
  str_world_boss_leveldesc_hard_7001110 = "- <color=#cc0e0e>Usar Habilidades Ativas</color> <color=#cc0e0e>gera 1 Ladrilho Escuro</color> dentro de 1 círculo ao redor do chefe.\n- Ataques Normais dos Aurorians reduzem pilhas de Veneno em si mesmos.\n- <color=#cc0e0e>Reduz o dano recebido</color> nas 8 ladrilhos externos do Chefe.\n- <color=#cc0e0e>Passar por um Ladrilho Escuro</color> <color=#cc0e0e>aumenta o ATQ</color> de todos os Aurorians na equipe.",
  str_world_boss_leveldesc_normal_7001111 = "- O Auroriano na posição de capitão inflige 1 instância extra de dano com cada Ataque Normal.",
  str_world_boss_leveldesc_hard_7001111 = "- O Auroriano na posição de capitão inflige 1 instância extra de dano com cada Ataque Normal.\n- Reduz o dano que os inimigos recebem de Habilidades Ativas em 80%.\n- Aumenta o dano recebido pelos inimigos de Ataques Normais em <color=#cc0e0e>30%</color>.",
  str_world_boss_bossdesc_7001111 = "Dano de Elemento Eficaz Aurorian +100%\nO Auroriano na posição de capitão inflige dano extra a cada Ataque Normal.",
  str_world_boss_leveldesc_normal_7001112 = "- Para cada ladrilho <color=#cc0e0e>vermelho</color> no campo, o dano final do Auroriano aumenta em <color=#cc0e0e>1%</color>.",
  str_world_boss_leveldesc_hard_7001112 = "- Para cada ladrilho <color=#cc0e0e>vermelho</color> no campo, o dano final do Auroriano aumenta em <color=#cc0e0e>1%</color>.\n- 2 Catadores aparecerão no campo, nos quais o Auroriano não pode infligir dano.\n- Os Catadores possuem uma <color=#cc0e0e>habilidade de contra-ataque</color> e se moverão após o Auroriano liberar uma Habilidade Ativa.",
  str_world_boss_bossdesc_7001112 = [[
Dano de Elemento Eficaz Aurorian +100%.
Ladrilhos vermelhos no campo aumentam o dano para Aurorianos.]],
  str_world_boss_leveldesc_normal_7001113 = "- Uma vez derrotado um inimigo, transforma a própria posição em um <color=#cc0e0e>ladrilho cromático</color>.",
  str_world_boss_leveldesc_hard_7001113 = "- Uma vez derrotando um inimigo, transforma a posição do próprio em um <color=#cc0e0e>ladrilho cromático</color>.\n- Com cada Ataque Normal, o Auroriano acumula pilhas, com cada pilha aumentando o dano da habilidade Combo em Cadeia em <color=#cc0e0e>3%</color>.\n- Reduz o dano que os inimigos recebem de Habilidades Ativas em <color=#cc0e0e>80%</color>.",
  str_world_boss_bossdesc_7001113 = "Dano de Elemento Eficaz Aurorian +100%\nGera ladrilhos cromáticos ao derrotar um inimigo planta.",
  str_world_boss_leveldesc_normal_7001114 = "- As habilidades de dano em área dos Aurorianos podem limpar ladrilhos de Marca de Veneno.",
  str_world_boss_leveldesc_hard_7001114 = "- As habilidades de Dano em Área dos Aurorianos podem ser usadas para remover as peças de Marca de Veneno.\n- No início da batalha e ao usar o Ataque das Borboletas, o chefe convoca muitas peças de Marca de Veneno.\n- A cada rodada, 1 <color=#cc0e0e>Peça Escura</color> aparecerá ao redor dos Aurorianos.",
  str_world_boss_bossdesc_7001114 = "Dano de Elemento Eficaz Aurorian +100%\nConverte ladrilhos de Marca de Veneno em Ladrilhos Escuros ao limpá-los",
  str_world_boss_leveldesc_normal_7001115 = "- Quando um atoleiro desaparece, a casa que ele ocupa se tornará da mesma cor que o Capitão.",
  str_world_boss_leveldesc_hard_7001115 = "- Quando um atoleiro desaparece, o ladrilho que ele ocupa se tornará da mesma cor que o Capitão.\n- Quando um atoleiro desaparece, o ladrilho que ele ocupa será automaticamente alterado para um <color=#cc0e0e>Ladrilho Escuro</color>.\n- Aumenta o dano da habilidade Combo em Cadeia do Auroriano, que é atualmente o Capitão, em <color=#cc0e0e>50%</color>.\n- O chefe é <color=#cc0e0e>imune ao ataque normal dos Aurorianos</color>.",
  str_world_boss_bossdesc_7001115 = "Dano de Contra-Elemento Auroriano +100%\nQuando um atoleiro desaparece, o ladrilho que ele ocupava se tornará da mesma cor que o Capitão",
  str_world_boss_bossdesc_7001119 = "Dano de Contra-Elemento Auroriano +100%\nGera um Ladrilho Escuro no local de um fantasma quando ele morre\n5 colunas de ladrilhos centradas no chefe movem-se para trás em 1 ladrilho a cada rodada",
  str_world_boss_leveldesc_normal_7001119 = "- Fantasmas geram um Bloco Escuro em sua localização quando morrem.\n- 5 colunas de blocos centradas no chefe recuam 1 bloco a cada rodada.",
  str_world_boss_leveldesc_hard_7001119 = "- Fantasmas geram Ladrilhos Escuros em sua localização quando morrem durante as rodadas dos Aurorianos.\n- 5 colunas de ladrilhos centradas no chefe recuam 1 ladrilho a cada rodada.\n- Passar por um Ladrilho Escuro aumenta o dano da Habilidade Ativa. Cada uso de uma Habilidade Ativa consome cargas.",
  str_world_boss_eliminate_mode = "Modo Iluminação",
  str_world_boss_eliminate = "Códice da Desolação da Iluminação",
  str_world_boss_eliminate_tip1 = "Modo de Iluminação do Códice da Desolação",
  str_world_boss_eliminate_tip2 = "O modo Iluminação para o Códice Desolação está de volta!\nNo modo Iluminação, não há necessidade de conectar ladrilhos; basta tocar nos ladrilhos para removê-los.\nDepois disso, os Aurorianos podem lançar Combos em Cadeia com base no número de ladrilhos removidos.",
  str_world_boss_bossdesc_7001121 = "Dano do Contra-Elemento Auroriano +100%.\nElimina a Arma de Salva e um Ladrilho Escuro será gerado no local.\nAumenta permanentemente o Dano do Ataque Normal após passar por um Ladrilho Escuro.",
  str_world_boss_bossdesc_7001123 = "O jogo termina quando a besta Nian destrói o portão e entra na cidade.\nDano de Contra-Elemento dos Aurorianos +100%.\nEntra na Hora da Aurora a cada outra rodada.\nLance uma Habilidade Ativa para assustar a besta Nian e fazê-la recuar.",
  str_world_boss_bossdesc_7001125 = "O Dano de Contra-Elemento dos Aurorianos +100%.\nApós a teletransportação, o Auroriano converte as telhas enfraquecidas próximas em telhas aprimoradas.",
  str_world_boss_bossdesc_7001126 = "Dano de Elemento Eficaz Aurorian +100%\nGanhos contam quando os Aurorianos usam Habilidades Ativas para causar dano, teleportar ou converter ladrilhos.\nA cada 3 contagens, o tempo de recarga da Habilidade Ativa Auroriana é reduzido em 1 rodada.\nA cada 3 contagens, o dano é causado ao chefe.",
  str_world_boss_bossdesc_7001127 = "O Dano de Contra-Elemento dos Aurorianos +100%.\nApós a teletransportação, os aurorianos ganham um escudo baseado na distância percorrida.",
  str_world_boss_bossdesc_7001128 = "O Contra-dano do Elemento dos Aurorianos +100%.\nGera um Ladrilho Escuro no local de um monstro quando ele é eliminado.",
  str_world_boss_bossdesc_7001129 = "Aumenta o contra-dano do elemento auroriano em 100%.\nOs chefes são imunes aos ataques normais dos aurorianos.\nTodos os requisitos de Combo em Cadeia dos aurorianos são reduzidos em 5 ladrilhos.",
  str_world_boss_bossdesc_7001132 = "O Dano do Contra-Elemento dos Aurorianos +100%.\nGera ladrilhos aprimorados nos locais de surgimento dos monstros.\nLadrilhos aprimorados ocupados por monstros serão convertidos em ladrilhos bloqueados antes das ações dos monstros.",
  str_world_boss_bossdesc_7001134 = "Aumenta o Dano de Elemento Eficaz Aurorian em +100%.\nO ATK auroriano aumenta permanentemente ao passar por Ladrilhos Escuros.\nO chefe convoca Eclipsitas menores adicionais quando está Enfurecido.\nEclipsitas menores transferem qualquer dano recebido para o chefe.\nEclipsitas menores deixam para trás Ladrilhos Escuros ao morrer.",
  str_world_boss_bossdesc_7001136 = "Dano do Contra-Elemento Auroriano +100%\nO dano de debuff do inimigo é significativamente aumentado.\nAs unidades Illumina são imunes ao dano de ataque direto.\nO dano sofrido pelas unidades Illumina é passado para o líder.",
  str_world_boss_bossdesc_7001137 = "Dano de Elemento Eficaz Aurorian +100%.\nOs ataques normais dos aurorianos causam 2 instâncias de dano.\nO chefe só recebe 10% de dano das Habilidades Ativas.",
  str_world_boss_multi_tips = "Durante o evento, as recompensas do Desolation Codex são triplicadas.",
  str_world_boss_bossdesc_7001142 = "Aumenta o contra-dano do elemento dos aurorianos em 100%.\nO dano aumenta à medida que a Sanidade se aproxima de 50.\nRestaura a Sanidade ao passar por ladrilhos escuros.\nReduz significativamente a Sanidade quando a cena desmorona.",
  str_world_boss_bossdesc_7001143 = "Aumenta o contra-dano do elemento auroriano em 100%.\nAumenta significativamente o dano ignorando a defesa dos aurorianos.\nGera ladrilhos escuros onde os monstros são derrotados.",
  str_world_boss_bossdesc_7001145 = "Aumenta o Dano de Elemento Eficaz Aurorian em 100%.\nO dano sofrido pelos faróis é transferido para o chefe.\nOs faróis sofrem mais danos de Combos em Cadeia, mas menos danos de Ataques Normais.\nOs aurorianos geram ladrilhos escuros cromáticos ao redor de si mesmos.",
  str_world_boss_bossdesc_7001146 = "Aumenta o Dano de Elemento Eficaz do Auroriano em 100%.\nGera um grande número de Ladrilhos Escuros ao redor do chefe.",
  str_world_boss_bossdesc_7002019 = "Aumenta o Dano de Contra-ataque do Elemento Auroriano em 100%.\nAcelera o tempo restante de recarga da habilidade do Auroriano em rodadas específicas.\nA execução contínua de Habilidades Ativas aumenta temporariamente o ATK da equipe.",
  str_world_boss_bossdesc_7001148 = "Dano de Contra-Elemento Auroriano +100%.\nGera um ladrilho aprimorado após esmagar uma pedrinha.",
  str_world_boss_bossdesc_7001149 = "Dano de Elemento Eficaz Aurorian +100%\nGera ladrilhos azuis escuros quando um inimigo é derrotado."
